package com.canteenpro.service;
import com.canteenpro.model.*;import com.canteenpro.dto.CheckoutRequest;import org.springframework.stereotype.Service;import java.util.*;import java.util.concurrent.atomic.AtomicLong;
@Service public class OrderService {private final Map<Long,Order> orders=new LinkedHashMap<>();private final AtomicLong seq=new AtomicLong(1);private final FoodService foods;public OrderService(FoodService foods){this.foods=foods;}public List<Order> all(){return new ArrayList<>(orders.values());}public Order get(Long id){Order o=orders.get(id);if(o==null)throw new RuntimeException("Order not found");return o;}public Order checkout(CheckoutRequest r){Order o=new Order();o.setId(seq.getAndIncrement());o.setUserId(r.getUserId());o.setCustomerName(r.getCustomerName());o.setEmail(r.getEmail());o.setPhone(r.getPhone());o.setAddress(r.getAddress());o.setPaymentMethod(r.getPaymentMethod()==null?"CASH":r.getPaymentMethod());double total=0;for(CheckoutRequest.Item i:r.getItems()){Food f=foods.get(i.getFoodId());if(i.getQuantity()<1)throw new RuntimeException("Quantity must be positive");foods.reduceStock(f.getId(),i.getQuantity());OrderItem oi=new OrderItem(f.getId(),f.getName(),i.getQuantity(),f.getPrice());o.getItems().add(oi);total+=oi.getSubtotal();}o.setTotal(total);orders.put(o.getId(),o);return o;}public Order status(Long id,String s){Order o=get(id);o.setStatus(s.toUpperCase());return o;}public Order payment(Long id,String s){Order o=get(id);o.setPaymentStatus(s.toUpperCase());return o;}public List<Order> byEmail(String email){return orders.values().stream().filter(o->email.equalsIgnoreCase(o.getEmail())).toList();}public void cancel(Long id){Order o=get(id);if(!"PENDING".equals(o.getStatus()))throw new RuntimeException("Only pending orders can be cancelled");o.setStatus("CANCELLED");}}